function isSignificantSecondaryComparison(comp) {
  const absPercentage = Math.abs(comp.percentageChange);
  switch (comp.metric) {
    case "p75":
      return absPercentage > 10;
    case "p95":
      return absPercentage > 20;
    case "p99":
      return absPercentage > 30;
    default:
      return comp.isSignificant;
  }
}
function formatRecommendation(overallTrend, improvements, degradations, confidenceScore) {
  const confidenceLevel = formatConfidenceLevel(confidenceScore);
  const recommendation = [
    `  - *Performance trend:* ${overallTrend} (${confidenceLevel} confidence, ${confidenceScore}% score). `
  ];
  switch (overallTrend) {
    case PERFORMANCE_TREND_TYPE.IMPROVED:
      recommendation.push(
        `  - Great job! Performance has improved across ${improvements.length} metrics. `
      );
      if (degradations.length > 0) {
        recommendation.push(
          `  - However, monitor the ${degradations.length} degraded metrics for potential regressions. `
        );
      }
      break;
    case PERFORMANCE_TREND_TYPE.DEGRADED:
      recommendation.push(`  - Performance has degraded across ${degradations.length} metrics.`);
      recommendation.push(
        "  - Investigate the root causes and consider rolling back changes that may have caused this regression."
      );
      if (improvements.length > 0) {
        recommendation.push(`  - *Note:* ${improvements.length} metrics showed improvement. `);
      }
      break;
    case PERFORMANCE_TREND_TYPE.STABLE:
      recommendation.push("  - Performance is stable with no significant changes detected.");
      break;
  }
  if (confidenceScore < 60) {
    recommendation.push(
      "  - Low confidence score suggests high variability or small sample size - consider running more tests for better accuracy."
    );
  }
  return recommendation.join("\n");
}
function formatConfidenceLevel(confidenceScore) {
  if (confidenceScore >= CONFIDENCE_LEVEL_THRESHOLDS.HIGH) {
    return CONFIDENCE_LEVEL_TYPE.HIGH;
  } else if (confidenceScore >= CONFIDENCE_LEVEL_THRESHOLDS.MEDIUM) {
    return CONFIDENCE_LEVEL_TYPE.MEDIUM;
  } else {
    return CONFIDENCE_LEVEL_TYPE.LOW;
  }
}

// src/commands/comparison.ts
async function executeComparison(performanceReport) {
  const comparisonConfig = resolveComparisonConfig();
  if (comparisonConfig?.enabled) {
    try {
      core5.info("Performance comparison enabled.");
      core5.info("Fetching baseline report...");
      const githubClient = new GitHubClient(
        comparisonConfig.githubToken,
        comparisonConfig.baselineRepo
      );
      const baselineData = await githubClient.getLatestBaselineReport(
        comparisonConfig.baselineWorkflow,
        comparisonConfig.applicationPlatform
      );
      core5.info("Generating comparison report...");
      const comparisonReporter = new PerformanceComparisonReporter();
      const comparisonReport = comparisonReporter.generate(
        performanceReport,
        baselineData.report,
        baselineData.metadata
      );
      const comparisonJsonOutput = JSON.stringify(comparisonReport);
      core5.setOutput("comparison-report", comparisonJsonOutput);
      const formattedReport = comparisonReporter.format(comparisonReport);
      core5.info(formattedReport);
      core5.setOutput("slack-report", formattedReport);
    } catch (comparisonError) {
      throw new Error(`Performance comparison failed: ${comparisonError}`);
    }
  }
}

// src/main.ts
async function run() {
  try {
    const testResult = await executeSyntheticsTests();
    const performanceReport = executePerformanceReport(testResult);
    await executeComparison(performanceReport);
  } catch (error2) {
    core6.setFailed(`Mobile performance test failed:
${error2}`);
  }
}
if (require.main === module) {
  run();
}
